import sys, json, re, hashlib

# THE OBJECTS HIVE AS A NODE SOURCE (GH #951, O.6): the graph space pulls an
# announced version of an object (`source_changed` from `./push`) on `in_read`
# with `outline` or `links`, and this cell answers from the head row -- the
# file space's answer shape (`{ok, file, version, nodes[] | links[], next}`),
# so the graph space reads both sources alike. An object has no `near`.
#
# Only the CURRENT version of an ACTIVE row is served: an older version, or a
# row that is no longer active, is `stale_version` (the graph space drops a
# stale pull); an id without a row is `unknown_source`. No round check here:
# the pull comes from the graph space, which stores the round of the source
# (`audience_set` of `source_changed`) at the node and filters every answer.
ME = "source"
SLOTS = ("what", "where", "who", "when", "why", "how")
ID_RE = re.compile(r"^ob-[0-9a-f]{12}$")
COLS = ["id", "rev", "type", "aliases", "state", "audience_set", "slots", "refs"]
LIMIT_MAX = 500


def loads(v, default):
    if isinstance(v, str):
        try:
            x = json.loads(v)
        except Exception:
            return default
        return x if isinstance(x, type(default)) else default
    return v if isinstance(v, type(default)) else default


def v12(oid, rev):
    return hashlib.sha256(("%s:%d" % (oid, int(rev))).encode("utf-8")).hexdigest()[:12]


# --8<-- object-graph
# The nodes and edges of one object row, ONE definition in two cells: `./source`
# answers `outline`/`links` with them and `./push` announces their counts on
# `source_changed`; `gh951_the_brief_is_deterministic_and_round_bound.rs` holds
# the two copies to one text. Root node anchor '' (the object), one node per
# filled slot `slot:<name>`; `who` shows as `<n> people`. Edges, all
# `extracted`: `owner` per person reference in `who`, `doc` per document
# address, `related` per object address. A one-liner is whole (R-IG-1,
# GH #1085: the 300-character cut is gone) -- the budget of the outline that
# lists it decides, not the node.
def _one(v):
    return " ".join(str(v or "").split())


def object_nodes(row):
    slots = loads(row.get("slots"), {})
    aliases = [a for a in loads(row.get("aliases"), []) if isinstance(a, str) and a]
    name = aliases[0] if aliases else str(row.get("id") or "")
    what = _one(slots.get("what"))
    out = [{"anchor": "", "kind": "object", "name": name,
            "oneline": "%s: %s" % (_one(row.get("type")), what or name),
            "parser": "objects"}]
    for s in SLOTS:
        v = slots.get(s)
        if s == "who":
            n = len([x for x in v if isinstance(x, str) and x]) if isinstance(v, list) else 0
            line = "%d people" % n if n else ""
        else:
            line = _one(v) if isinstance(v, str) else ""
        if line:
            out.append({"anchor": "slot:" + s, "kind": "slot", "name": s,
                        "oneline": line, "parser": "objects"})
    return out


def object_links(row):
    slots = loads(row.get("slots"), {})
    refs = loads(row.get("refs"), {})
    out = []
    for kind, targets in (("owner", slots.get("who")), ("doc", refs.get("doc")),
                          ("related", refs.get("related"))):
        for t in targets if isinstance(targets, list) else []:
            if isinstance(t, str) and t:
                out.append({"kind": kind, "from_anchor": "", "target_name": t,
                            "class": "extracted"})
    return out
# --8<-- end object-graph


def emit(msgs):
    for m in msgs:
        if isinstance(m, dict) and "messages" not in m:
            m["messages"] = []
    sys.stdout.write(json.dumps(msgs, ensure_ascii=False))
    sys.exit(0)


def answer(c, fields):
    body = dict(fields)
    body["header"] = {"route": "answer", "op": str(c.get("op") or ""),
                      "op_id": str(c.get("op_id") or ""), "source": str(c.get("source") or "")}
    return body


def refuse(c, code, message):
    return answer(c, {"ok": False, "file": str(c.get("source") or ""),
                      "error": {"code": code, "message": message}})


doc = json.load(sys.stdin)
d = doc.get("body") or {}
h = (doc.get("envelope") or {}).get("header") or {}
hop = h.get("hop") or {}
ctx = h.get("context") or {}
lane = str(hop.get("route") or "")

if lane == "in_read":
    args = d.get("args") if isinstance(d.get("args"), dict) else {}
    file_ = str(d.get("file") or "")
    S = str(d.get("source") or hop.get("source") or file_.split("@", 1)[0]).strip()
    version = str(args.get("version") or d.get("version")
                  or (file_.split("@", 1)[1] if "@" in file_ else "")).strip().lower()
    try:
        limit = max(1, min(LIMIT_MAX, int(args.get("limit") or LIMIT_MAX)))
    except Exception:
        limit = LIMIT_MAX
    c = {"op": str(hop.get("op") or d.get("op") or ""), "op_id": str(hop.get("op_id") or ""),
         "source": S, "version": version[:12], "limit": limit}
    if c["op"] not in ("outline", "links"):
        emit([refuse(c, "unknown_op", "an object answers outline and links")])
    if not ID_RE.match(S):
        emit([refuse(c, "unknown_source", "no such source")])
    emit([{"header": {"route": "source_store", "phase": "read", "reply_cell": ME,
                      "cur_call": json.dumps(c, sort_keys=True)},
           "messages": [{"origin": "assistant", "type": "tool_call", "id": "h",
                         "text": json.dumps({"operation": "select", "table": "objects",
                                             "columns": COLS, "where": {"id": S},
                                             "order_by": [{"col": "rev", "dir": "desc"}],
                                             "limit": 1})}]}])

if lane:
    sys.stderr.write("objects/source: unknown lane %r -- dropped\n" % lane)
    emit([])

c = loads(ctx.get("cur_call"), {})
if str(ctx.get("cur_phase") or "") != "read" or not hop.get("operation"):
    sys.stderr.write("objects/source: a message with neither a lane nor a store answer\n")
    emit([])
rows = []
for m in d.get("messages") or []:
    if isinstance(m, dict) and m.get("id") == "h":
        rows = loads(m.get("text"), [])
if hop.get("error_code"):
    emit([refuse(c, "store_error", "the store refused the read")])
head = rows[0] if rows and isinstance(rows[0], dict) else None
if head is None:
    emit([refuse(c, "unknown_source", "no such source")])
if head.get("state") != "active" or v12(head["id"], head.get("rev") or 0) != c.get("version"):
    emit([refuse(c, "stale_version", "not the current version of an active object")])
fields = {"ok": True, "file": head["id"], "version": c["version"], "next": ""}
if c["op"] == "outline":
    fields["nodes"] = object_nodes(head)[:int(c.get("limit") or LIMIT_MAX)]
else:
    fields["links"] = object_links(head)[:int(c.get("limit") or LIMIT_MAX)]
emit([answer(c, fields)])
